import type { LexicalEditor } from "lexical";

export function isLexicalEditor(value: unknown): value is LexicalEditor {
  if (typeof value !== "object" || value === null) {
    return false;
  }

  const editor = value as Record<string, unknown>;
  return (
    typeof editor.getEditorState === "function" &&
    typeof editor.getRootElement === "function" &&
    typeof editor.update === "function" &&
    typeof editor.read === "function"
  );
}

